module max_flow_solver (input clk, input rst_n, input start, input [1:0] source, input [1:0] sink, input [1:0] num_nodes, input [5:0] edge_count, input [15:0] capacity [0:3][0:3], output reg [15:0] max_flow, output reg [5:0] used_edges, output reg [1:0] out_u, output reg [1:0] out_v, output reg [15:0] out_flow, output reg out_valid, output reg done); parameter IDLE = 3'd0; parameter INIT = 3'd1; parameter BFS_SEARCH = 3'd2; parameter AUGMENT = 3'd3; parameter OUTPUT = 3'd4; parameter DONE = 3'd5; reg [2:0] state; reg [15:0] residual [4][4]; reg [15:0] original_capacity [4][4]; reg [1:0] parent [4]; reg [3:0] visited; reg [1:0] bfs_queue [3:0]; reg [2:0] queue_count; reg [1:0] queue_head; reg [15:0] total_flow; reg [5:0] used_edges_count; reg [15:0] current_flow_value; reg [1:0] current_u; reg [1:0] current_v; reg [3:0] output_index; always @(posedge clk) begin if (!rst_n) begin state <= IDLE; max_flow <= 0; used_edges <= 0; out_u <= 0; out_v <= 0; out_flow <= 0; out_valid <= 0; done <= 0; residual <= 0; original_capacity <= 0; parent <= 0; visited <= 0; bfs_queue <= 0; queue_count <= 0; queue_head <= 0; total_flow <= 0; used_edges_count <= 0; output_index <= 0; end else begin case (state) IDLE: if (start) state <= INIT; else state <= IDLE; INIT: residual <= capacity; original_capacity <= capacity; state <= BFS_SEARCH; BFS_SEARCH: if (queue_count > 0) begin [1:0] u = bfs_queue[queue_head]; queue_head = (queue_head + 1) % 4; queue_count = queue_count - 1; if (u == sink) state <= AUGMENT; for (int v=0; v<4; v++) begin if (residual[u][v] > 0 && !visited[v]) begin visited[v] <= 1'b1; parent[v] <= u; if (queue_count < 4) begin [1:0] write_idx = {queue_head + queue_count}; bfs_queue[write_idx[1:0]] <= v; queue_count <= queue_count + 1; end end end else begin state <= DONE; done <= 1'b1; end AUGMENT: state <= OUTPUT; OUTPUT: if (output_index < 16) begin [1:0] u = {output_index[1:0], output_index[2:0]}; [1:0] v = {output_index[3:0], output_index[4:0]}; if (u < num_nodes && v < num_nodes) begin [15:0] flow_val = original_capacity[u][v] - residual[u][v]; if (flow_val > 0) begin out_u <= u; out_v <= v; out_flow <= flow_val; out_valid <= 1'b1; output_index <= output_index + 1; used_edges_count <= used_edges_count + 1; end else begin out_valid <= 1'b0; output_index <= output_index + 1; end end else begin out_valid <= 1'b0; output_index <= output_index + 1; end end else begin output_index <= 0; out_valid <= 1'b0; end state <= OUTPUT; DONE: state <= DONE; endcase end end endmodule